"""Apply UI110 after the exact UI109 runtime; read-only browsing changes."""
from __future__ import annotations
import base64,hashlib,json,sys,zlib
from pathlib import Path,PurePosixPath
PARENT_MANIFEST_SHA256='37270fa93be13d6ba247300095d9f042b23a4310d7ef64e4e9ee6f3680c7e370'
TARGET_VARIANT='workspace-ui110-tasks-maintenance-browsing-2026-10-13'
FILES={'UI_PATCH.json': {'before': '15fcdb355507596b85ee66677db60baeae1a4ca6c4090cdcd45bca380897887a', 'after': '9a280a4f672953698bdeebae227bb6d67e2d48ee3fa512c14585b5ac0c6b4184', 'bytes': 2801, 'payload': ''}, 'app/static/index.html': {'before': 'cec72a2bb03dcf9c9ca46f2daea9819bd4aecc911caa7f2ee9d35b45155b4cb8', 'after': 'e49244a2e67781e26b2cbdd0bc32a023009ae8f11d817d2eb6c3973cf448225b', 'bytes': 24839, 'payload': ''}, 'app/static/maintenance_workspace.css': {'before': '6c7c12b7c8d68e9230fcb8d62207cea20e9d28d5598a50ba213780494d08db45', 'after': 'ead615b858e7d53e1bcec5adc9b2175f8ccd9eaf15dbf0137b068a7f150214d1', 'bytes': 14689, 'payload': ''}, 'app/static/maintenance_workspace.js': {'before': 'c0270beafaac75ae866c9aa9db021cf62044870b054a333d9783f04b6e32cd5f', 'after': 'cad4a866358822523fc5e0e045da36a71d3b44eabf2f02d6bddf5802def26012', 'bytes': 24453, 'payload': ''}, 'app/static/sw.js': {'before': 'a0954c4b1eaebdd4997447d0e570f087dd55cb6250a33c453cf40952586b7c01', 'after': '2805c5f2a9fcdf937af2939706fa84e03c5ace13e269f5102ccf40720192b540', 'bytes': 13523, 'payload': ''}, 'app/static/task_workspace.css': {'before': 'f2f9e7da267c4043e412cd0a05619cc0efd1e95f677d985e03a74166ffc87aa7', 'after': '40bb67d5a83b0ff7f03eae106e471641cf94627984bcd23eaf911e53f0ebf96e', 'bytes': 13157, 'payload': ''}, 'app/static/task_workspace.js': {'before': 'eca13368e44300648ef2fedb14c483d85f39d7e3a0f6ce638c16a931155e477e', 'after': 'cfaf53486d5adadc46a100d267a0e30f02430a3240077e1e2271545b56c8caab', 'bytes': 27182, 'payload': ''}, 'app/static/work_execution_ui80.css': {'before': '2e15aa54a3ccf468a1ad1cfae6339425d5e30e3714fc8da3ba1596a0c475cc1f', 'after': 'a224dd8bc8db95b6b1b56cfcfba2c06a677bec45a007d53382d2e2ea4404c6d2', 'bytes': 151950, 'payload': ''}, 'tests/ui110_maintenance/__init__.py': {'before': None, 'after': 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'bytes': 0, 'payload': 'eNoDAAAAAAE='}, 'tests/ui110_maintenance/browser_checks.py': {'before': None, 'after': '9e94b50762db2a4806523efbdd8d674b2c5c2362fb0b65bada4687f1269a6bdb', 'bytes': 10495, 'payload': ''}}

def apply(destination: Path) -> None:
    manifest_path=destination/'RELEASE_FILES.json'
    raw=manifest_path.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=PARENT_MANIFEST_SHA256:
        raise ValueError('UI110 requires the exact UI109 source manifest. Do not deploy.')
    manifest=json.loads(raw)
    for name,expected in manifest['files'].items():
        relative=PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise ValueError('Unsafe source manifest path.')
        path=destination.joinpath(*relative.parts)
        if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:
            raise ValueError('UI110 parent resource mismatch: '+name)
    prepared={}
    for name,record in FILES.items():
        path=destination/name
        if record['before'] is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('UI110 new resource already exists: '+name)
        elif manifest['files'].get(name)!=record['before']:
            raise ValueError('UI110 parent file mismatch: '+name)
        dec=zlib.decompressobj()
        data=dec.decompress(base64.b64decode(record['payload'],validate=True),record['bytes']+1)
        data+=dec.flush()
        if not dec.eof or dec.unused_data or dec.unconsumed_tail or len(data)!=record['bytes'] or hashlib.sha256(data).hexdigest()!=record['after']:
            raise ValueError('UI110 payload integrity failure: '+name)
        prepared[name]=data
    for name,data in prepared.items():
        path=destination/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
        manifest['files'][name]=FILES[name]['after']
    manifest['variant']=TARGET_VARIANT
    manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
    for name,expected in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('Derived UI110 integrity failure: '+name)

if __name__=='__main__':
    apply(Path(sys.argv[1]))
    print('Applied Workspace UI110: compact Tasks and Maintenance browsing; saved work and existing actions retained.')
